public class ContainerWithMostWater {
    public int maxArea(int[] height) {
        int left = 0, right = height.length - 1;
        int maxArea = 0;

        while (left < right) {
            // 计算当前容器面积
            int w = right - left;
            int h;
            if (height[left] < height[right]) {
                h = height[left];
                left++;   // 移动短板（左）
            } else {
                h = height[right];
                right--;  // 移动短板（右）
            }
            maxArea = Math.max(maxArea, h * w);
        }
        return maxArea;
    }

    public static void main(String[] args) {
        ContainerWithMostWater sol = new ContainerWithMostWater();
        int[] h1 = {1, 8, 6, 2, 5, 4, 8, 3, 7};
        System.out.println(sol.maxArea(h1)); // 49

        int[] h2 = {1, 1};
        System.out.println(sol.maxArea(h2)); // 1

        int[] h3 = {4, 3, 2, 1, 4};
        System.out.println(sol.maxArea(h3)); // 16

        int[] h4 = {1, 2, 1};
        System.out.println(sol.maxArea(h4)); // 2
    }
}
